function runTrieOps(ops) {
  const root = { children: new Map(), isEnd: false };

  function insert(word) {
    let node = root;
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, { children: new Map(), isEnd: false });
      node = node.children.get(ch);
    }
    node.isEnd = true;
  }

  function findNode(str) {
    let node = root;
    for (const ch of str) {
      if (!node.children.has(ch)) return null;
      node = node.children.get(ch);
    }
    return node;
  }

  const output = [];
  for (const [op, arg] of ops) {
    if (op === "insert") {
      insert(arg);
    } else if (op === "search") {
      const node = findNode(arg);
      output.push(!!node && node.isEnd);
    } else if (op === "startsWith") {
      output.push(findNode(arg) !== null);
    }
  }
  return output;
}
